"""Test support for the lifted Janitor tests: a $KREW_HOME whose janitor.yaml has the crew's shape (the units,
probes, holds and flags the crew's own janitor runs with, names scrubbed), with every path in a temp folder.
Importing this sets KREW_JANITOR_CONFIG for the session (conftest gives each test its own empty KREW_HOME)."""
from __future__ import annotations

import os
import tempfile
from pathlib import Path

HOME_DIR = Path(tempfile.mkdtemp(prefix="krew-janitor-test-"))
SETTINGS = '# The machine\'s own krew Janitor settings (copy to ~/.krew/janitor.yaml): config/janitor.example.yaml with the\n# values scripts/krew-janitor.py runs with today (generated by tools/mk_janitor_yaml.py from its constants).\npaths:\n  metrics_dir: \'@metrics_dir@\'\n  id_root: \'@id_root@\'\n  render_jobs: \'@render_jobs@\'\ncards:\n  profile: ada\n  created_by: krew-janitor\n  cooldown_s: 43200\nunits:\n  watch: ["ops.service", "crew.service", "voiceonly-home.service", "face-shell.service", "zoey-display.service", "rail-camera.service", "rail-presence.service", "ear-bridge.service", "ws-shadow.service", "hermes-ada-gateway.service", "hermes-zoey-gateway.service", "hermes-dashboard.service", "rail-stt.service", "audio8-asr.service", "audio8-tts.service", "crew-announce-drain.service", "enroll-panel.service", "inspector-stamp.service", "vllm-log.service", "crew-keeper.service", "crew-conductor.service", "crew-conductor-bench.service", "crew-lila-conductor.service", "crew-lila-takes.service", "crew-lila-doctor.service"]\n  report_only: ["crew.service", "ops.service"]\n  observe_only: ["rail-camera.service", "rail-presence.service", "zoey-display.service"]\n  retired: ["inspector-stamp.service"]\n  retired_probes: ["inspector-stamp"]\n  glass_unit: zoey-display.service\n  glass_mode_file: ~/.hermes/crew-glass-mode\nprobes:\n  timeout_s: 8\n  ports: {"ops": [8000, "/v1/models"], "crew": [8005, "/v1/models"], "live-ear": [8096, "/health"], "rail-stt": [8190, "/health"], "rail-presence": [8191, "/v1/health"], "rail-camera": [8192, "/v1/health"], "ws-shadow": [8093, "/health"], "voice": [7789, "/health"], "audio8-tts": [8024, "/api/health"], "voiceonly-home": [8099, "/health"], "crew-clip-doctor": [8199, "/health"], "conductor": [8100, "/v1/health"], "conductor-bench": [8110, "/v1/health"], "lila-conductor": [8101, "/v1/health"], "lila-takes": [8198, "/health"], "lila-doctor": [8212, "/map"], "comfy": [8188, "/system_stats"], "face-shell": [8088, "/v1/house"], "enroll-panel": [8196, "/"], "vllm-log": [8086, "/health"], "zoey-gw": [8652, "/health"], "ada-gw": [8653, "/health"], "dashboard": [9119, "/"]}\n  units: {"ops": "ops.service", "crew": "crew.service", "live-ear": "live-ear.service", "rail-stt": "rail-stt.service", "rail-presence": "rail-presence.service", "rail-camera": "rail-camera.service", "ws-shadow": "ws-shadow.service", "audio8-tts": "audio8-tts.service", "voiceonly-home": "voiceonly-home.service", "conductor": "crew-conductor.service", "conductor-bench": "crew-conductor-bench.service", "lila-conductor": "crew-lila-conductor.service", "lila-takes": "crew-lila-takes.service", "lila-doctor": "crew-lila-doctor.service", "face-shell": "face-shell.service", "enroll-panel": "enroll-panel.service", "inspector-stamp": "inspector-stamp.service", "vllm-log": "vllm-log.service", "zoey-gw": "hermes-zoey-gateway.service", "ada-gw": "hermes-ada-gateway.service", "dashboard": "hermes-dashboard.service"}\nrestart:\n  armed: false                      # the machine runs armed (unit Environment=KREW_JANITOR_RESTART=1)\n  cooldown_s: 1800\n  never: ["crew-conductor.service", "crew-wall-ascii.service"]\ncrash_loop:\n  restarts: 2\n  window_s: 300\n  signatures: ["CUDA out of memory", "illegal memory access", "EngineDeadError"]\ngpu:\n  occupancy_units: ["voice.service", "crew.service", "ops.service"]\n  occupancy_probes: ["comfy", "voice", "crew", "ops"]\n  mode_file: ~/.hermes/crew-gpu-mode\n  pending_file: ~/.hermes/crew-gpu-pending\n  beast_hold: /run/hermes/beast-hold\n  beast_parked_units: ["ops.service"]\n  beast_parked_probes: ["ops"]\n  render_parked_units: ["crew.service"]\n  render_parked_probes: ["crew"]\n  render_sleep_units: ["hermes-zoey-gateway.service"]\ntrain:\n  busy_flag: /run/hermes/train-busy\n  busy_max_age_s: 21600\n  parked_units: ["crew.service", "ops.service"]\n  parked_probes: ["voice", "crew", "ops"]\n  hold_paths: [/tmp/crew-train-hold, <memory store>/train-hold]\naudio:\n  probe: true\n  reap: true                       # unit Environment=KREW_JANITOR_AUDIO_REAP=1\nlogs:\n  roots: [/var/log, ~/.hermes, ~/projects, ~/agents]\nregistry:\n  name_prefixes: [krew-, crew-, rail-, zoey-, voiceonly-, hermes-]\n  exec_markers: [/the rails repo, ~/projects/rail-, <envs>, ~/.hermes]\nwatch:\ngate_hold:\n  suites:\n    kanban-board-gate: [tests/test_kanban_board_gate.py, tests/test_kanban_board_gate_zoey_down.py, tests/test_kanban_cause.py, tests/test_gate_strikes.py, tests/test_gate_janitor_topology.py]\n    kanban-loop: [tests/test_kanban_loop.py, tests/test_kanban_loop_archive_verb.py, tests/test_kanban_loop_done_verb.py, tests/test_kanban_loop_ruler_reframe.py]\n    decomposer: [tests/test_ada_decomposer_key.py]\ncrystal:\n  delight_dir: display/delight-lab\ncode_canary:\n  hermes_dir: ~/.hermes\n  envs_root: <envs>\n  service_envs: [audio8-tts, comfyui, hindsight, rail-stt, unsloth, unsloth-train, vllm, vllm-0271-cu132, wespeaker]\n  code_trees: {the rails repo/lib: ~/projects/<rails-repo>/lib, the rails repo/scripts: ~/projects/<rails-repo>/scripts}\n  ms_unit: nightly-tests.service\n  recipe: docs/checkpoints/restore-repair-20260923/README.md\nzoeyos:\n  units: [crew-conductor.service, crew-conductor-bench.service, face-shell.service, zoey-display.service, rail-stt.service, ear-bridge.service]\n  probes: [conductor, conductor-bench, rail-stt, face-shell]\n  unit_patterns: [zoeyos-*]\n'
for k in ("metrics_dir", "id_root", "render_jobs"):
    SETTINGS = SETTINGS.replace("@" + k + "@", str(HOME_DIR / k))
(HOME_DIR / "janitor.yaml").write_text(SETTINGS, encoding="utf-8")
os.environ["KREW_JANITOR_CONFIG"] = str(HOME_DIR / "janitor.yaml")
